// Commit message, PR and comment conventions. [id, targets, pattern, text, bad, good, options]
export const GIT_TEXT = [
  ['commit-no-fixup', ['commits'], R`^(?:fixup|squash|amend)! `, 'Squash fixup! and squash! commits before pushing.', 'fixup! Add retry to the uploader', 'Add retry to the uploader'],
  ['commit-no-wip', ['commits'], R`^\s*\[?wip\]?\b`, 'No WIP commits on shared branches.', 'WIP uploader', 'Add the upload queue', { flags: 'i' }],
  ['commit-no-merge-branch', ['commits'], R`^Merge branch '[^']+' (?:of|into)\b`, 'Rebase instead of merging main into feature branches.', "Merge branch 'main' into feature", 'Rebase on main'],
  ['commit-no-skip-ci', ['commits'], R`\[(?:skip ci|ci skip|no ci)\]`, 'Never skip CI in commit messages.', 'Bump version [skip ci]', 'Bump version to 1.4.1', { flags: 'i' }],
  ['commit-no-placeholder-subject', ['commits'], R`^(?:asdf|test|tmp|temp|update|fix|changes|stuff|misc)\s*$`, 'Write a commit subject that says what changed.', 'fix', 'Fix the off-by-one in pagination', { flags: 'i' }],
  ['commit-no-gerrit-change-id', ['commits'], R`^Change-Id:\s*I[0-9a-f]{40}`, 'This repo does not use Gerrit; drop Change-Id trailers.', 'Change-Id: I8473b95934b5732ac55d26311a706c9c2bde9940', 'Refs: API-12'],
  ['commit-no-this-commit', ['commits'], R`\bthis commit\b`, 'Write what the change does, not "This commit".', 'This commit adds caching to the API client.', 'Cache API responses for 60 seconds.', { flags: 'i' }],
  ['commit-no-past-tense-ticket', ['commits'], R`^(?:Resolved|Closed|Fixed) (?:issue|ticket|bug) #?\d+`, 'Reference issues with "Fixes #123" in the body, not a past-tense subject.', 'Fixed issue #42', 'Handle empty carts in checkout'],
  ['commit-no-jira-in-subject-brackets', ['commits'], R`^\[[A-Z]{2,10}-\d+\]`, 'Put ticket keys in the body as "Refs: ABC-123", not in brackets at the start.', '[PAY-12] Retry failed charges', 'Retry failed charges'],
  ['commit-no-dependabot-style-bump', ['commits'], R`^Bumps? [\w@/.-]+ from \d[\w.]* to \d`, 'Dependency bumps go through Renovate, not hand-written "Bumps x from" commits.', 'Bump lodash from 4.17.20 to 4.17.21', 'Update lockfile after Renovate merge'],
  ['commit-no-revert-revert', ['commits'], R`^Revert "Revert "`, 'Do not revert a revert; reapply the change with a new message.', 'Revert "Revert "Add caching""', 'Reapply caching with the TTL fix'],
  ['commit-no-at-mentions', ['commits'], R`(?<![\w.<])@[A-Za-z][\w-]{1,38}\b(?![\w.-]*\.\w)`, 'No @mentions in commit messages; they notify people on every rebase.', 'Thanks @octocat for the report', 'Reported in issue #88'],
  ['pr-no-this-pr', ['pr'], R`\bThis PR\b`, 'Do not start PR prose with "This PR"; say what changed.', 'This PR adds caching.', 'Adds a 60 second cache to the API client.'],
  ['pr-no-imgur', ['pr', 'comments'], R`\bi\.imgur\.com/`, 'Attach screenshots to the PR instead of linking external image hosts.', '![shot](https://i.imgur.com/abc123.png)', '![shot](./shot.png)'],
  ['pr-no-checklist-boxes', ['pr'], R`^\s*-\s*\[\s\]\s`, 'No unchecked task boxes in PR bodies; finish the work or leave it out.', '- [ ] Update docs', '- Docs updated in README'],
  ['pr-no-closes-in-title', ['pr'], R`^(?:Closes|Fixes|Resolves) #\d+\s*$`, 'PR titles describe the change; put "Fixes #123" in the body.', 'Fixes #42', 'Handle empty carts in checkout'],
  ['pr-no-ai-disclaimer', ['pr', 'comments'], R`\b(?:written|generated|created) (?:by|with|using) (?:AI|an AI|ChatGPT|Copilot|GPT-\d)\b`, 'No AI-generated disclaimers in PRs or comments.', 'This description was generated by AI.', 'Adds retry logic to the uploader.', { flags: 'i' }],
  ['comment-no-lgtm-only', ['comments'], R`^\s*(?:LGTM|lgtm|\+1|:\+1:|bump)\s*!?\s*$`, 'Review comments say what you checked, not just LGTM or +1.', 'LGTM', 'Checked the retry path locally; the backoff caps at 30 s.'],
  ['comment-no-sorry', ['comments'], R`\b(?:sorry|apologies) for (?:the|any) (?:delay|confusion|inconvenience)\b`, 'Skip apologies in GitHub comments; state the update.', 'Sorry for the delay, here is the fix.', 'Pushed the fix in 3f2c1a.', { flags: 'i' }],
  ['comment-no-friendly-ping', ['comments'], R`\b(?:friendly|gentle) (?:ping|reminder)\b`, 'No "friendly ping" comments; ask a concrete question.', 'Friendly ping on this!', 'Can you confirm the API change is fine for mobile?', { flags: 'i' }],
  ['comment-no-closing-in-favor-of-nothing', ['comments'], R`^\s*closing\.?\s*$`, 'A bare "Closing." comment explains nothing; say why.', 'Closing.', 'Closing: superseded by #61, which keeps the retry loop.', { flags: 'i' }],
  ['pr-no-wip-title', ['pr'], R`^\s*(?:\[WIP\]|WIP:)`, 'Open a draft PR instead of a [WIP] title.', '[WIP] New uploader', 'New uploader'],
  ['pr-no-todo-in-body', ['pr'], R`\bTODO\b`, 'No TODOs in PR bodies; open an issue and link it.', 'TODO: add tests later', 'Tests cover the retry path.'],
  ['pr-no-long-lines-in-title', ['pr'], R`^.{120,}$`, 'Keep PR titles and body lines under 120 characters.', 'Add a very long description of the change that keeps going well past the one hundred and twenty character limit for lines', 'Add retry to the uploader'],
]

// Naming conventions not tied to one framework. [id, glob, pattern, text, bad, good, options]
export const NAMING = [
  ['naming-react-component-pascal', 'jsx', R`^\s*(?:export\s+)?function\s+[a-z]\w*\s*\(\s*\{[^}]*\}\s*\)\s*\{\s*$`, 'React components are PascalCase.', 'export function userCard({ user }) {', 'export function UserCard({ user }) {'],
  ['naming-no-redux-action-camel', 'jsts', R`type:\s*['"][a-z]+[A-Z]\w*['"]`, 'Action types use domain/eventName form, for example "cart/itemAdded".', "dispatch({ type: 'addItem' })", "dispatch({ type: 'cart/itemAdded' })"],
  ['naming-no-handle-prefix-props', 'jsx', R`\bhandle[A-Z]\w*=\{`, 'Props are named onX; handlers are named handleX.', '<Button handleClick={save} />', '<Button onClick={save} />'],
  ['naming-constants-upper', 'jsts', R`^\s*export\s+const\s+(?:max|min|default)[A-Z]\w*\s*=\s*\d`, 'Exported numeric constants are SCREAMING_SNAKE_CASE.', 'export const maxRetries = 3', 'export const MAX_RETRIES = 3'],
  ['naming-no-is-not', 'jsts', R`\b(?:const|let)\s+isNot[A-Z]\w*`, 'Name booleans positively (isVisible, not isNotHidden).', 'const isNotReady = !ready', 'const isReady = ready'],
  ['naming-no-plural-enum', 'ts', R`\b(?:enum|type)\s+\w+(?:Types|Statuses|Kinds)\b`, 'Type and enum names are singular.', 'type OrderStatuses = "open" | "closed"', 'type OrderStatus = "open" | "closed"'],
  ['naming-no-impl-suffix', 'java', R`\bclass\s+\w+Impl\b`, 'No Impl suffix; name the implementation for what makes it different.', 'class UserServiceImpl implements UserService {', 'class JdbcUserService implements UserService {'],
  ['naming-no-manager-classes', 'kt', R`\bclass\s+\w+(?:Manager|Helper|Util)\b`, 'Avoid Manager, Helper and Util class names; name the responsibility.', 'class SessionManager(', 'class SessionStore('],
  ['naming-go-acronyms', 'go', R`\b(?:Http|Url|Json|Id|Api|Sql)[A-Z]\w*\b|\b\w+(?:Http|Url|Json|Id|Api)\b(?=\s*[(:=])`, 'Go initialisms keep one case: HTTP, URL, ID, API.', 'func parseUrl(raw string) {', 'func parseURL(raw string) {'],
  ['naming-swift-no-get', 'swift', R`\bfunc\s+get[A-Z]\w*\(\)\s*->`, 'Swift getters are properties, not getX() functions.', 'func getName() -> String {', 'var name: String {'],
  ['naming-py-private-single-underscore', 'py', R`^\s*def\s+__[a-z]\w*[^_]\(`, 'Use a single underscore for private methods; double underscores mangle names.', 'def __load(self):', 'def _load(self):'],
  ['naming-py-constants-upper', 'py', R`^(?:max|min|default)_[a-z_]+\s*=\s*\d`, 'Module constants are UPPER_SNAKE_CASE.', 'max_retries = 3', 'MAX_RETRIES = 3'],
  ['naming-rust-no-camel-fn', 'rs', R`\bfn\s+[a-z]+[A-Z]\w*\s*[<(]`, 'Rust functions are snake_case.', 'fn parseHeader(input: &str) {', 'fn parse_header(input: &str) {'],
  ['naming-sql-no-tbl-prefix', 'sql', R`\bCREATE\s+TABLE\s+(?:IF\s+NOT\s+EXISTS\s+)?"?tbl_?`, 'No tbl prefixes on table names.', 'CREATE TABLE tbl_users (', 'CREATE TABLE users (', { flags: 'i' }],
  ['naming-css-no-bem-violation', 'css', R`\.[a-z-]+__[a-z-]+__[a-z-]+`, 'BEM blocks nest one element level only.', '.card__header__title {', '.card__title {'],
  ['naming-test-files-describe-unit', 'jstest', R`\bdescribe\(\s*['"](?:tests?|misc|stuff|it works)['"]`, 'describe blocks name the unit under test.', "describe('tests', () => {", "describe('formatPrice', () => {"],
  ['naming-kt-no-underscore-backing', 'kt', R`private\s+val\s+_[a-z]\w*\s*=\s*(?!MutableStateFlow|MutableLiveData|MutableSharedFlow)`, 'Use _name only for backing properties of mutable flows.', 'private val _client = HttpClient()', 'private val client = HttpClient()'],
  ['naming-branch-kebab', null, R`\bgit\s+(?:checkout\s+-b|switch\s+-c|branch)\s+\S*[A-Z_]`, 'Branch names are lowercase-kebab, for example fix/upload-retry.', 'git checkout -b Fix_Upload', 'git checkout -b fix/upload-retry', { targets: ['commands'] }],
  ['naming-no-generic-file-utils', 'jsts', R`from\s+['"][./]+(?:utils|helpers|misc|common)['"]`, 'Do not import from catch-all utils or helpers modules; import the specific module.', "import { format } from '../utils'", "import { formatPrice } from '../price/format'"],
]
